std::vector<cg3::Point2d> convexHull2D(const std::vector<cg3::Point2d>& points) {
    if (points.size() <= 1) {
        return points;
    }

    // Find the point with minimum y-coordinate (and minimum x-coordinate in case of tie)
    auto min_it = std::min_element(points.begin(), points.end(), 
        [](const cg3::Point2d& a, const cg3::Point2d& b) {
            return a.y() < b.y() || (a.y() == b.y() && a.x() < b.x());
        });

    cg3::Point2d pivot = *min_it;

    // Sort points by polar angle with respect to pivot
    std::vector<cg3::Point2d> sorted_points = points;
    std::sort(sorted_points.begin(), sorted_points.end(), 
        [&pivot](const cg3::Point2d& a, const cg3::Point2d& b) {
            double dx1 = a.x() - pivot.x();
            double dy1 = a.y() - pivot.y();
            double dx2 = b.x() - pivot.x();
            double dy2 = b.y() - pivot.y();

            double cross = dx1 * dy2 - dx2 * dy1;
            if (cross != 0) {
                return cross > 0; // Counter-clockwise
            }

            // If collinear, closer point comes first
            return dx1 * dx1 + dy1 * dy1 < dx2 * dx2 + dy2 * dy2;
        });

    // Remove duplicate points
    auto last = std::unique(sorted_points.begin(), sorted_points.end());
    sorted_points.erase(last, sorted_points.end());

    if (sorted_points.size() <= 2) {
        return sorted_points;
    }

    // Graham scan
    std::vector<cg3::Point2d> hull;
    hull.push_back(sorted_points[0]);
    hull.push_back(sorted_points[1]);

    for (size_t i = 2; i < sorted_points.size(); i++) {
        while (hull.size() >= 2) {
            const cg3::Point2d& p2 = hull[hull.size() - 1];
            const cg3::Point2d& p1 = hull[hull.size() - 2];
            const cg3::Point2d& p0 = sorted_points[i];

            // Cross product to determine orientation
            double cross = (p2.x() - p1.x()) * (p0.y() - p1.y()) - 
                          (p2.y() - p1.y()) * (p0.x() - p1.x());

            if (cross <= 0) {
                hull.pop_back();
            } else {
                break;
            }
        }
        hull.push_back(sorted_points[i]);
    }

    return hull;
}

